# -*- coding: utf-8 -*-
"""生成 `eval_confirmed_golden_test.go`：用**原版模型模块**算确认信号的黄金值。

这是整个量价移植里最关键的比对：它比的是**最终信号本身**
（价格/打分/风险级别/命中与未命中清单/解释文本/子类型/行为质量/子度量），
而不是中间量。信号直接决定组合买什么。

覆盖：8 种形态 × 3 种市场状态 × 3 个模型 = 72 组。

用法：

    python internal/volprice/testdata/gen_eval_confirmed_golden.py \
        --original "D:\\workspace\\python\\stock\\tushare-stock-tonyz\\pythonProject\\pythonProject" \
        --out internal/volprice/eval_confirmed_golden_test.go
"""

from __future__ import annotations

import argparse
import importlib.util
import json
import math
import os
import shutil
import subprocess
import sys

MODELS = ("trend_pullback", "box_range", "oversold_rebound")
STATES = ("bull", "range", "bear")


def go_str(value) -> str:
    return json.dumps(str(value), ensure_ascii=False)


def go_float(value) -> str:
    if value is None:
        return "nan()"
    f = float(value)
    if math.isnan(f):
        return "nan()"
    if math.isinf(f):
        return "math.Inf(1)" if f > 0 else "math.Inf(-1)"
    return repr(f)


def go_str_slice(values) -> str:
    if not values:
        return "nil"
    return "[]string{" + ", ".join(go_str(v) for v in values) + "}"


def load_series(here):
    spec = importlib.util.spec_from_file_location(
        "gen_prefilter_golden", os.path.join(here, "gen_prefilter_golden.py")
    )
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return list(module.load_metrics_series(here)) + [
        ("trend_start", module.series_trend_start),
        ("pullback_reclaim", module.series_pullback_reclaim),
        ("crash", module.series_crash),
        ("box", module.series_box),
        ("box_buy", module.series_box_buy),
        ("oversold_buy", module.series_oversold_buy),
    ]


def sub_metric_map(metrics):
    """把子度量整成 数值/布尔 → float 的映射（字符串键丢掉，单独比）。"""
    out = {}
    for key, value in (metrics or {}).items():
        if isinstance(value, bool):
            out[key] = 1.0 if value else 0.0
        elif isinstance(value, (int, float)) and not isinstance(value, bool):
            out[key] = float(value)
    return out


def extras_map(behavior_quality):
    """behavior_quality 里被合并进来的额外数值键（原实现 dict.update 的产物）。

    用数值映射而不是文本，避免 Python `repr(float)` 与 Go 格式化不一致带来的假失败。
    """
    base_keys = {
        "volume_behavior", "volume_behavior_label", "acceptance_quality",
        "acceptance_quality_label", "upper_shadow_behavior",
        "upper_shadow_behavior_label", "score", "death_volume_risk",
    }
    out = {}
    for key, value in (behavior_quality or {}).items():
        if key in base_keys:
            continue
        if isinstance(value, bool):
            out[key] = 1.0 if value else 0.0
        elif isinstance(value, (int, float)):
            out[key] = float(value)
    return out


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--original", required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args()

    if args.original not in sys.path:
        sys.path.insert(0, args.original)

    import pandas as pd  # noqa: E402
    import volume_price_features as vpf  # noqa: E402
    import volume_price_models as vpm  # noqa: E402

    here = os.path.dirname(os.path.abspath(__file__))
    series = load_series(here)

    lines = []
    lines.append("// Code generated by testdata/gen_eval_confirmed_golden.py; DO NOT EDIT.")
    lines.append("//")
    lines.append("// 黄金值由**原版 volume_price_models._evaluate_confirmed_prepared** 跑出。")
    lines.append("package volprice")
    lines.append("")
    import_index = len(lines)

    lines.append("type goldenEvalSignal struct {")
    lines.append("\tOK bool")
    lines.append("\tModelID string")
    lines.append("\tModelName string")
    lines.append("\tMarketState string")
    lines.append("\tMarketStateLabel string")
    lines.append("\tSignalType string")
    lines.append("\tSignalLevel string")
    lines.append("\tSignalLevelLabel string")
    lines.append("\tSignalSubtype string")
    lines.append("\tSignalSubtypeLabel string")
    lines.append("\tSignalDate string")
    lines.append("\tEntryPrice float64")
    lines.append("\tStopPrice float64")
    lines.append("\tTargetPrice float64")
    lines.append("\tScore float64")
    lines.append("\tRiskLevel string")
    lines.append("\tHits []string")
    lines.append("\tMisses []string")
    lines.append("\tExplanation string")
    lines.append("\tBehaviorScore float64")
    lines.append("\tBehaviorDeath bool")
    lines.append("\tVolumeBehavior string")
    lines.append("\tAcceptanceQuality string")
    lines.append("\tUpperShadowBehavior string")
    lines.append("\tBehaviorExtras map[string]float64")
    lines.append("\tQualityBlockReasons []string")
    lines.append("\tCandidateTriggerPrice float64")
    lines.append("\tEarlyMainTrend map[string]float64")
    lines.append("\tTrendPlatform map[string]float64")
    lines.append("\tBoxQuality map[string]float64")
    lines.append("\tOversoldQuality map[string]float64")
    lines.append("}")
    lines.append("")
    lines.append("type goldenEvalCase struct {")
    lines.append("\tName string")
    lines.append("\tMarketState string")
    lines.append("\tBars []goldenBar")
    lines.append("\tByModel map[string]goldenEvalSignal")
    lines.append("}")
    lines.append("")
    lines.append("var goldenEvalCases = []goldenEvalCase{")
    lines.append("")

    hits_total, ok_total = 0, 0
    for name, builder in series:
        frame = builder(pd)
        prepared = vpf.prepare_bars(frame)
        for state in STATES:
            entry = {}
            for model in MODELS:
                signal = vpm._evaluate_confirmed_prepared(model, prepared, state)
                if signal:
                    ok_total += 1
                    hits_total += 1
                entry[model] = signal
            lines.append("\t{")
            lines.append("\t\tName: %s," % go_str(name))
            lines.append("\t\tMarketState: %s," % go_str(state))
            lines.append("\t\tBars: []goldenBar{")
            for _, row in frame.iterrows():
                lines.append(
                    "\t\t\t{%s, %s, %s, %s, %s, %s},"
                    % (
                        go_str(row["trade_date"]), go_float(row["open"]), go_float(row["high"]),
                        go_float(row["low"]), go_float(row["close"]), go_float(row["volume"]),
                    )
                )
            lines.append("\t\t},")
            lines.append("\t\tByModel: map[string]goldenEvalSignal{")
            for model in MODELS:
                signal = entry[model]
                lines.append("\t\t\t%s: {" % go_str(model))
                lines.append("\t\t\t\tOK: %s," % ("true" if signal else "false"))
                if signal:
                    behavior = signal.get("behavior_quality") or {}
                    lines.append("\t\t\t\tModelID: %s," % go_str(signal.get("model_id", "")))
                    lines.append("\t\t\t\tModelName: %s," % go_str(signal.get("model_name", "")))
                    lines.append("\t\t\t\tMarketState: %s," % go_str(signal.get("market_state", "")))
                    lines.append("\t\t\t\tMarketStateLabel: %s," % go_str(signal.get("market_state_label", "")))
                    lines.append("\t\t\t\tSignalType: %s," % go_str(signal.get("signal_type", "")))
                    lines.append("\t\t\t\tSignalLevel: %s," % go_str(signal.get("signal_level", "")))
                    lines.append("\t\t\t\tSignalLevelLabel: %s," % go_str(signal.get("signal_level_label", "")))
                    lines.append("\t\t\t\tSignalSubtype: %s," % go_str(signal.get("signal_subtype", "")))
                    lines.append("\t\t\t\tSignalSubtypeLabel: %s," % go_str(signal.get("signal_subtype_label", "")))
                    lines.append("\t\t\t\tSignalDate: %s," % go_str(signal.get("signal_date", "")))
                    lines.append("\t\t\t\tEntryPrice: %s," % go_float(signal.get("entry_price")))
                    lines.append("\t\t\t\tStopPrice: %s," % go_float(signal.get("stop_price")))
                    lines.append("\t\t\t\tTargetPrice: %s," % go_float(signal.get("target_price")))
                    lines.append("\t\t\t\tScore: %s," % go_float(signal.get("score")))
                    lines.append("\t\t\t\tRiskLevel: %s," % go_str(signal.get("risk_level", "")))
                    lines.append("\t\t\t\tHits: %s," % go_str_slice(signal.get("condition_hits") or []))
                    lines.append("\t\t\t\tMisses: %s," % go_str_slice(signal.get("condition_misses") or []))
                    lines.append("\t\t\t\tExplanation: %s," % go_str(signal.get("explanation", "")))
                    lines.append("\t\t\t\tBehaviorScore: %s," % go_float(behavior.get("score")))
                    lines.append("\t\t\t\tBehaviorDeath: %s," % ("true" if behavior.get("death_volume_risk") else "false"))
                    lines.append("\t\t\t\tVolumeBehavior: %s," % go_str(behavior.get("volume_behavior", "")))
                    lines.append("\t\t\t\tAcceptanceQuality: %s," % go_str(behavior.get("acceptance_quality", "")))
                    lines.append("\t\t\t\tUpperShadowBehavior: %s," % go_str(behavior.get("upper_shadow_behavior", "")))
                    lines.append("\t\t\t\tBehaviorExtras: map[string]float64{")
                    extras = extras_map(behavior)
                    for k in sorted(extras):
                        lines.append("\t\t\t\t\t%s: %s," % (go_str(k), go_float(extras[k])))
                    lines.append("\t\t\t\t},")
                    lines.append("\t\t\t\tQualityBlockReasons: %s," % go_str_slice(signal.get("quality_block_reasons") or []))
                    lines.append("\t\t\t\tCandidateTriggerPrice: %s," % go_float(signal.get("candidate_trigger_price")))

                    feature = signal.get("feature") if isinstance(signal.get("feature"), dict) else {}
                    for field, key in (
                        ("EarlyMainTrend", "early_maintrend_start"),
                        ("TrendPlatform", "trend_platform"),
                        ("BoxQuality", "box_quality"),
                        ("OversoldQuality", "oversold_quality"),
                    ):
                        values = sub_metric_map(feature.get(key))
                        lines.append("\t\t\t\t%s: map[string]float64{" % field)
                        for k in sorted(values):
                            lines.append("\t\t\t\t\t%s: %s," % (go_str(k), go_float(values[k])))
                        lines.append("\t\t\t\t},")
                lines.append("\t\t\t},")
            lines.append("\t\t},")
            lines.append("\t},")

    lines.append("}")
    lines.append("")

    if "math.Inf" in "\n".join(lines):
        lines[import_index:import_index] = ["import \"math\"", ""]

    os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
    with open(args.out, "w", encoding="utf-8", newline="\n") as handle:
        handle.write("\n".join(lines))
    gofmt = shutil.which("gofmt")
    if gofmt:
        subprocess.run([gofmt, "-w", args.out], check=True)

    print(f"wrote {args.out}: {len(series)*len(STATES)} cases, "
          f"{hits_total} signals produced (of {len(series)*len(STATES)*len(MODELS)} model-state combos)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
